role_constraints.query:
DEFINE EDGE Marriage {
  husband <- (ONE) ALLOWS Person {
    constraints: { of_age: husband.age >= 18 }
  },
  wife <- (ONE) ALLOWS Person {
    constraints: { of_age: wife.age >= 18 }
  },
  date
};

indexing.query:
DEFINE FIELD Embedding: Vector<384> @index(vector, metric="cosine");

MATCH (p:Person)
WHERE VECTOR_SIMILARITY(p.Embedding, $query_embedding) > 0.8
RETURN p
ORDER BY VECTOR_SIMILARITY(p.Embedding, $query_embedding) DESC
LIMIT 10;

pattern_matching.query:
MATCH (p:Person)
RETURN p.Name,
  MATCH p.Status {
    ACTIVE => "Currently Active",
    PENDING => "Awaiting Approval",
    INACTIVE => "Not Active",
    _ => "Unknown Status"
  } AS status_label;

data_modeling.example:
DEFINE EDGE Meeting {
  organizer <- (ONE) ALLOWS Person,
  attendees <- (MANY) ALLOWS Person,
  date,
  location
};

